import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class AbstractScopeBuilder_shouldTraverse_TriageGen2Test {

    private TestScopeBuilder scopeBuilder;
    private NodeTraversal mockTraversal;

    // Concrete implementation for testing since AbstractScopeBuilder is abstract
    private static class TestScopeBuilder extends TypedScopeCreator.AbstractScopeBuilder {
        private Scope mockScope;

        public TestScopeBuilder(Scope scope) {
            this.mockScope = scope;
        }

        @Override
        public Scope getScope() {
            return mockScope;
        }

        @Override
        public void visit(NodeTraversal t, Node n, Node parent) {
            // Implementation not needed for shouldTraverse testing
        }

        // Mocking the internal method used in the logic
        @Override
        protected void defineFunctionLiteral(Node n, Node parent) {
            // No-op for testing
        }
    }

    private Scope mockScope;

    @Before
    public void setUp() {
        mockScope = mock(Scope.class);
        scopeBuilder = new TestScopeBuilder(mockScope);
        mockTraversal = mock(NodeTraversal.class);
        when(mockTraversal.getInputId()).thenReturn("testId");
    }

    @Test
    public void testShouldTraverse_ParentIsNull() {
        Node n = createNode(NodeType.VAR);

        // descend = parent == null (true)
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, null));
    }

    @Test
    public void testShouldTraverse_ParentIsNotFunction() {
        Node n = createNode(NodeType.VAR);
        Node parent = createNode(NodeType.BLOCK);

        // descend = !parent.isFunction() (true)
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_IsFirstChildOfFunction() {
        Node parent = createNode(NodeType.FUNCTION);
        Node n = createNode(NodeType.VAR);
        parent.addChild(n);

        // descend = n == parent.getFirstChild() (true)
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_ParentIsRoot() {
        Node root = createNode(NodeType.BLOCK);
        Node parent = createNode(NodeType.FUNCTION);
        Node n = createNode(NodeType.VAR);

        parent.addChild(n);
        when(mockScope.getRootNode()).thenReturn(root);
        // To make parent == scope.getRootNode(), we need to make parent the root
        // However, the condition is parent == scope.getRootNode()
        // Let's set parent as root
        Node rootParent = createNode(NodeType.FUNCTION);
        when(mockScope.getRootNode()).thenReturn(rootParent);

        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, rootParent));
    }

    @Test
    public void testShouldTraverse_ReturnsFalseForBodyOfFunction() {
        Node parent = createNode(NodeType.FUNCTION);
        Node n = createNode(NodeType.VAR);
        parent.addChild(n);

        // n is NOT first child (if we add something else)
        Node firstChild = createNode(NodeType.EXPRESSION);
        parent.addChild(firstChild);
        parent.addChild(n);

        when(mockScope.getRootNode()).thenReturn(createNode(NodeType.BLOCK));

        // descend = parent.isFunction() && n != firstChild && parent != root
        assertFalse(scopeBuilder.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_FunctionOrScriptNode() {
        Node n = createNode(NodeType.FUNCTION);
        // This triggers Preconditions.checkNotNull(inputId) and sourceName assignment
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, null));
    }

    @Test
    public void testShouldTraverse_HoistedFunctionDetection() {
        Node n = createNode(NodeType.BLOCK); // Statement parent
        Node hoisted = createNode(NodeType.FUNCTION);
        // NodeUtil.isHoistedFunctionDeclaration logic is internal/static, 
        // but we test the branch coverage by providing a child.
        n.addChild(hoisted);

        // We need to ensure NodeUtil.isStatementParent(n) returns true.
        // In JSComp, a BLOCK is a statement parent.

        // Since we cannot easily mock static NodeUtil, this test verifies 
        // the code path reaches the loop.
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, null));
    }

    @Test(expected = NullPointerException.class)
    public void testShouldTraverse_ThrowsWhenInputIdIsNullOnFunction() {
        when(mockTraversal.getInputId()).thenReturn(null);
        Node n = createNode(NodeType.FUNCTION);

        // Should throw Preconditions.checkNotNull
        scopeBuilder.shouldTraverse(mockTraversal, n, null);
    }
}
